import { ReactNode } from "react";
import { Meta, StoryObj } from "@storybook/react";
import { useArgs, useGlobals } from "storybook/preview-api";
import { showcaseParameters, showsAllThemesParameters, themes } from "@/storybook/preview";
import {
  DesignTokenGroup,
  DesignTokenPage,
  PaletteOverview,
  getTokenNames,
  parseTokenGroups,
} from "./design-tokens-storybook-helpers";
import { ThemeMatrix } from "./design-tokens-matrix-storybook-helpers";
import foundationSource from "./foundation.less?raw";
import componentSource from "./component.less?raw";
import commonSource from "./common.less?raw";
import gronalundSource from "./parks/gronalund.less?raw";
import kolmardenSource from "./parks/kolmarden.less?raw";
import furuvikSource from "./parks/furuvik.less?raw";
import sommarlandSource from "./parks/sommarland.less?raw";
import vildmarkshotelletSource from "./parks/vildmarkshotellet.less?raw";

const parkTokenNames = getTokenNames(
  [gronalundSource, kolmardenSource, furuvikSource, sommarlandSource, vildmarkshotelletSource].flatMap((source) =>
    parseTokenGroups(source),
  ),
);

/** Tokens that only parks set, such as the park palettes. Only the names, the values are read from the theme. */
const getParkOnlyTokens = (prefix: string, sharedGroups: Array<DesignTokenGroup>) => {
  const sharedNames = new Set(getTokenNames(sharedGroups));
  const names = parkTokenNames.filter((name) => name.startsWith(prefix) && !sharedNames.has(name));
  return [...new Set(names)].map((name) => ({ name }));
};

const getParkOnlyGroup = (prefix: string, file: string, sharedGroups: Array<DesignTokenGroup>) => ({
  title: "Set only by parks",
  notes: [`Not in ${file}, only set by one or more parks in src/theming/parks/, so they are empty in the others.`],
  tokens: getParkOnlyTokens(prefix, sharedGroups),
  isParkOnly: true,
});

const foundationGroups = parseTokenGroups(foundationSource);
const parkColorGroup = {
  title: "Park colors",
  notes: ["Set per park in src/theming/parks/. Pick a park or theme in the toolbar to see its palette."],
  tokens: getParkOnlyTokens("--foundation-", foundationGroups),
};
const foundationPageGroups = [parkColorGroup, ...foundationGroups];

const componentGroups = parseTokenGroups(componentSource);
const componentPageGroups = [getParkOnlyGroup("--component-", "component.less", componentGroups), ...componentGroups];

const commonGroups = parseTokenGroups(commonSource);
const commonPageGroups = [getParkOnlyGroup("--common-", "common.less", commonGroups), ...commonGroups];

const HowToRead = ({ allThemes }: { allThemes: string }) => (
  <p>
    All values are shown for the theme selected in the toolbar (the paintbrush), so switch theme to see how a park or
    theme changes them, or pick <strong>Alla teman</strong> to {allThemes}. The line under a value is its default in the
    code, which a park or theme can override. Click a token to copy it as <code>var(--token-name)</code>, which is how
    it is used in CSS.
  </p>
);

/** Completes "pick Alla teman to ..." in HowToRead */
const matrixAllThemesText = "compare every token in every theme side by side";

const HowToReadMatrix = () => (
  <p>
    Every token in every theme side by side: a row per token and a column per theme, grouped by park. A token that is
    the same in all themes is shown as one line. Hover a cell to see its value, or click a theme name to open that theme
    on its own. Themes with a hatched name are not yet complete and are still being corrected, so missing values and low
    contrast are expected there.
  </p>
);

type DesignTokenArgs = {
  /** The group picked on the Component and Common stories, e.g. `cards` */
  group?: string;
};

// Storybook only takes an arg from the URL when the story has an argType for it, so a link can open on a group
const groupArgTypes: Story["argTypes"] = {
  group: { control: false, description: "The picked group, e.g. `cards`. Kept in the URL." },
};

type TokenPageOptions = {
  groups: Array<DesignTokenGroup>;
  intro: ReactNode;
  /** The intro for "Alla teman" */
  matrixIntro: ReactNode;
  /** What a group is called in the picker, e.g. `Component` */
  pickerLabel: string;
  /** The picker's option for all groups, e.g. `All components` */
  pickerAllLabel: string;
};

/** The token list, or the theme matrix for "Alla teman", with a group picker kept in the `group` arg */
const renderWithThemeMatrix = ({
  groups,
  intro,
  matrixIntro,
  pickerLabel,
  pickerAllLabel,
}: TokenPageOptions): NonNullable<Story["render"]> =>
  function TokenPageWithThemeMatrix(_args, { globals }) {
    const [, updateGlobals] = useGlobals();
    const [{ group }, updateArgs, resetArgs] = useArgs<DesignTokenArgs>();
    const groupPicker = {
      label: pickerLabel,
      allLabel: pickerAllLabel,
      selected: group,
      onSelect: (slug?: string) => (slug ? updateArgs({ group: slug }) : resetArgs(["group"])),
    };

    return (
      <DesignTokenPage
        theme={globals.theme}
        groups={groups}
        intro={intro}
        groupPicker={groupPicker}
        allThemesView={
          <ThemeMatrix
            groups={groups}
            themes={themes}
            intro={matrixIntro}
            onOpenTheme={(theme) => updateGlobals({ theme })}
            groupPicker={groupPicker}
          />
        }
      />
    );
  };

const meta = {
  title: "Foundation/Design tokens",
  // An autogenerated Docs page would only repeat the first story
  tags: ["!autodocs"],
  parameters: {
    ...showcaseParameters,
    // A reference page without a snapshot, see "The other exception is a reference page" in docs/storybook.md
    chromatic: { disableSnapshot: true },
  },
} satisfies Meta<DesignTokenArgs>;

export default meta;

type Story = StoryObj<DesignTokenArgs>;

export const Foundation: Story = {
  render: (_args, { globals }) => (
    <DesignTokenPage
      theme={globals.theme}
      groups={foundationPageGroups}
      allThemesView={<PaletteOverview group={parkColorGroup} />}
      intro={
        <>
          <h1 className="heading-l">Foundation tokens</h1>
          <p>
            The building blocks of the design system: colors, typography, spacing, border radius, widths and shadows.
            Components use them directly or through component tokens.
          </p>
          <HowToRead allThemes="compare the palettes of every theme" />
        </>
      }
    />
  ),
};

export const Component: Story = {
  parameters: showsAllThemesParameters,
  argTypes: groupArgTypes,
  render: renderWithThemeMatrix({
    groups: componentPageGroups,
    pickerLabel: "Component",
    pickerAllLabel: "All components",
    intro: (
      <>
        <h1 className="heading-l">Component tokens</h1>
        <p>
          Tokens for a single component or component type, built on the foundation tokens. Parks and themes often
          override these, for example to change the color of a button.
        </p>
        <HowToRead allThemes={matrixAllThemesText} />
      </>
    ),
    matrixIntro: (
      <>
        <h1 className="heading-l">Component tokens in all themes</h1>
        <HowToReadMatrix />
      </>
    ),
  }),
};

const commonDeprecationNotice = (
  <>
    <strong>Being phased out.</strong> Do not use these in new designs or code, use foundation or component tokens
    instead.
  </>
);

export const Common: Story = {
  name: "Common (deprecated)",
  parameters: showsAllThemesParameters,
  argTypes: groupArgTypes,
  render: renderWithThemeMatrix({
    groups: commonPageGroups,
    pickerLabel: "Group",
    pickerAllLabel: "All groups",
    intro: (
      <>
        <h1 className="heading-l">Common tokens (deprecated)</h1>
        <p>{commonDeprecationNotice} They are listed here because existing components still use them.</p>
        <HowToRead allThemes={matrixAllThemesText} />
      </>
    ),
    matrixIntro: (
      <>
        <h1 className="heading-l">Common tokens (deprecated) in all themes</h1>
        <p>{commonDeprecationNotice}</p>
        <HowToReadMatrix />
      </>
    ),
  }),
};
