type AlmostAnything<T> =
  | T
  | Array<T>
  | undefined
  | null
  | boolean
  | Map<unknown, unknown>
  | Record<string | number | symbol, unknown>;

export const isNonEmptyArray = <T>(arr: AlmostAnything<T>): arr is Array<T> => {
  return arr instanceof Array && arr.length > 0;
};

// We have null here since `sortIndex` might come from Contentful, which sets missing values to null rather than undefined
type WithSortIndex = { sortIndex?: number | null };
export const sortIndexComparer = (a: WithSortIndex, b: WithSortIndex) => {
  if (typeof a.sortIndex !== "number" || typeof b.sortIndex !== "number") {
    if (a.sortIndex && !b.sortIndex) {
      // B doesn't have a property sortIndex, but A has
      return -1;
    }
    if (!a.sortIndex && b.sortIndex) {
      // A doesn't have a property sortIndex, but B has
      return 1;
    }
    return 0;
  }
  if (a.sortIndex < b.sortIndex) {
    return -1;
  } else if (a.sortIndex > b.sortIndex) {
    return 1;
  }
  return 0;
};

export const isTruthy = <T>(value: T): value is Exclude<T, false | null | undefined> => !!value;

/**
 * Groups an array of items by a key generated by the keyGetter function.
 * Groups will be ordered by the first occurrence of the key in the input array.
 * Items in each group will also be ordered by their original order in the input array.
 */
export const groupBy = <T, K extends string | number | symbol | boolean | null | undefined>(
  array: Array<T>,
  keyGetter: (item: T) => K,
): Array<{ key: K; items: Array<T> }> => {
  const groups: Array<{ key: K; items: Array<T> }> = [];
  for (const item of array) {
    const key = keyGetter(item);

    let group = groups.find((g) => g.key === key);
    if (!group) {
      group = { key, items: [] };
      groups.push(group);
    }
    group.items.push(item);
  }
  return groups;
};
