import { CSSProperties, ReactNode, useLayoutEffect, useMemo, useRef, useState } from "react";
import { useCopyToClipboard } from "@/core/hooks";
import { capitalizeFirstLetter, groupBy, isTruthy, multipleClassNames } from "@/core/helpers";
import { ALL_THEMES } from "@/storybook/preview";
import styles from "./design-tokens.stories.module.less";

export type DesignToken = {
  /** The CSS custom property, e.g. `--foundation-spacing-x4` */
  name: string;
  /** The value as written in the less file, e.g. `var(--foundation-spacing-x1)` */
  definition?: string;
  /** The comment after the declaration, if any */
  comment?: string;
};

export type DesignTokenGroup = {
  title: string;
  /** Comment lines inside the group that are not headings */
  notes: Array<string>;
  tokens: Array<DesignToken>;
  /** Marks the group of tokens that only parks set */
  isParkOnly?: boolean;
};

const HEADING_PATTERN = /^\/\/\s*=+\s*(.+?)\s*=+$/;
const DECLARATION_PATTERN = /^(--[\w-]+)\s*:\s*(.*)$/;
// `.color-palette(primary; gronalund-core-color-green);` declares its nine tokens in design-system-theming-template.less
const COLOR_PALETTE_PATTERN = /^\.color-palette(-inverted)?\(\s*([\w-]+)\s*;\s*([\w-]+)\s*\)/;
// Same as @color-palette-steps in design-system-theming-template.less
const COLOR_PALETTE_STEPS = [100, 200, 300, 400, 500, 600, 700, 800, 900];
// Comments that only repeat the value in px are left out, the page calculates px itself.
const PX_COMMENT_PATTERN = /^-?\d*\.?\d+px$/;

/** Headings written in capitals (e.g. `GIFT DELIVERY METHOD`) are shown in sentence case like the rest */
const formatHeading = (heading: string) =>
  heading === heading.toUpperCase() ? capitalizeFirstLetter(heading.toLowerCase()) : heading;

/**
 * Reads the CSS custom properties in a theming less file, grouped by its
 * `// ============== Title ==============` headings
 */
export const parseTokenGroups = (source: string): Array<DesignTokenGroup> => {
  const groups: Array<DesignTokenGroup> = [];
  let currentGroup: DesignTokenGroup | undefined;
  // A declaration can span several lines, it ends at the first `;`
  let pending: { name: string; text: string } | undefined;

  const addToken = (name: string, text: string) => {
    const [value, ...rest] = text.split(";");
    const comment = rest
      .join(";")
      .trim()
      .replace(/^\/\/\s*/, "");
    const definition = value.replace(/\s+/g, " ").replace(/\(\s/g, "(").replace(/\s\)/g, ")").trim();
    // A comment ending with `;` is a commented-out declaration, not a description of the token
    const isDescription = comment && !PX_COMMENT_PATTERN.test(comment) && !comment.endsWith(";");

    if (!currentGroup) {
      currentGroup = { title: "Other", notes: [], tokens: [] };
      groups.push(currentGroup);
    }
    currentGroup.tokens.push({ name, definition, comment: isDescription ? comment : undefined });
  };

  for (const rawLine of source.split(/\r?\n/)) {
    const line = rawLine.trim();

    if (pending) {
      pending.text += ` ${line}`;
    } else {
      const heading = line.match(HEADING_PATTERN);
      const declaration = line.match(DECLARATION_PATTERN);
      const colorPalette = line.match(COLOR_PALETTE_PATTERN);

      if (heading) {
        currentGroup = { title: formatHeading(heading[1]), notes: [], tokens: [] };
        groups.push(currentGroup);
      } else if (line.startsWith("//")) {
        currentGroup?.notes.push(line.replace(/^\/\/\s*/, ""));
      } else if (declaration) {
        pending = { name: declaration[1], text: declaration[2] };
      } else if (colorPalette) {
        const [, inverted, role, corePalette] = colorPalette;
        COLOR_PALETTE_STEPS.forEach((step) => {
          const coreStep = inverted ? 1000 - step : step;
          addToken(`--foundation-color-${role}-${step}`, `@${corePalette}-${coreStep};`);
        });
      }
    }

    if (pending?.text.includes(";")) {
      addToken(pending.name, pending.text);
      pending = undefined;
    }
  }

  return groups.filter((group) => group.tokens.length > 0);
};

type PreviewType =
  | "fill"
  | "shadow"
  | "radius"
  | "spacing"
  | "font-size"
  | "font-weight"
  | "font-family"
  | "line-height"
  | "letter-spacing";

const CSS_WIDE_KEYWORDS = ["inherit", "initial", "unset", "revert", "revert-layer"];

const fillCache = new Map<string, boolean>();

/** Whether a resolved value can be painted as a background: a color or a gradient */
export const isFillValue = (value: string) => {
  if (!fillCache.has(value)) {
    const isFill =
      !!value &&
      !CSS_WIDE_KEYWORDS.includes(value) &&
      (CSS.supports("color", value) || (value.includes("gradient(") && CSS.supports("background-image", value)));
    fillCache.set(value, isFill);
  }
  return fillCache.get(value) === true;
};

/** Picks how a token is visualised, from its name and the value it resolves to in the current theme */
const getPreviewType = (name: string, value: string): PreviewType | undefined => {
  if (!value || CSS_WIDE_KEYWORDS.includes(value)) return undefined;
  if (name.includes("shadow") && CSS.supports("box-shadow", value)) return "shadow";
  if (isFillValue(value)) return "fill";
  if (name.includes("border-radius")) return "radius";
  if (name.includes("font-size")) return "font-size";
  if (name.includes("font-weight")) return "font-weight";
  if (name.includes("font-family")) return "font-family";
  if (name.includes("line-height")) return "line-height";
  if (name.includes("letter-spacing")) return "letter-spacing";
  if (name.includes("spacing") && CSS.supports("width", value)) return "spacing";
  return undefined;
};

const Swatch = ({ name, className }: { name: string; className: string }) => (
  <span className={className}>
    <span style={{ background: `var(${name})` }} />
  </span>
);

const TokenPreview = ({ name, value }: { name: string; value: string }) => {
  const token = `var(${name})`;

  switch (getPreviewType(name, value)) {
    case "fill":
      return <Swatch name={name} className={styles.swatch} />;
    case "shadow":
      return <div className={styles.box} style={{ boxShadow: token }} />;
    case "radius":
      return <div className={styles.box} style={{ borderRadius: token }} />;
    case "spacing":
      return <div className={styles.bar} style={{ width: token }} />;
    case "font-size":
      return (
        <span className={styles.fontSize} style={{ fontSize: token }}>
          Aa
        </span>
      );
    case "font-weight":
      return <span style={{ fontWeight: token }}>Aa</span>;
    case "font-family":
      return <span style={{ fontFamily: token }}>Aa Åå Öö</span>;
    case "line-height":
      return (
        <span className={styles.lineHeight} style={{ lineHeight: token }}>
          Ag
          <br />
          Ag
        </span>
      );
    case "letter-spacing":
      return <span style={{ letterSpacing: token }}>Letter spacing</span>;
    default:
      return null;
  }
};

/** Copies `var(--token-name)` on click */
const CopyTokenButton = ({
  name,
  className,
  style,
  children,
}: {
  name: string;
  className: string;
  style?: CSSProperties;
  children: (copied: boolean) => ReactNode;
}) => {
  const usage = `var(${name})`;
  const { copied, copyToClipboard } = useCopyToClipboard(usage);

  return (
    <button type="button" className={className} style={style} title={`Copy ${usage}`} onClick={copyToClipboard}>
      {children(copied)}
    </button>
  );
};

export type TokenNameButtonProps = { name: string };

export const TokenNameButton = ({ name }: TokenNameButtonProps) => (
  <CopyTokenButton name={name} className={styles.tokenName}>
    {(copied) => (
      <>
        <code>{name}</code>
        {copied && <span className={styles.copied}>Copied</span>}
      </>
    )}
  </CopyTokenButton>
);

/** Adds the px value to single rem values, since designers usually work in px */
export const formatValue = (value: string, rootFontSize: number) => {
  const rem = value.match(/^(-?\d*\.?\d+)rem$/);
  return rem ? `${value} (${Number((parseFloat(rem[1]) * rootFontSize).toFixed(2))}px)` : value;
};

/** The text a search matches a token against. `values` has the resolved value in each shown theme. */
export const getSearchText = (
  group: DesignTokenGroup,
  token: DesignToken,
  values: Array<string | undefined>,
  rootFontSize: number,
) =>
  [
    group.title,
    token.name,
    token.definition,
    token.comment,
    ...values.filter(isTruthy).map((value) => formatValue(value, rootFontSize)),
  ]
    .filter(isTruthy)
    .join(" ")
    .toLowerCase();

export const getSearchQuery = (search: string) => search.trim().toLowerCase();

export const getTokenNames = (groups: Array<DesignTokenGroup>) =>
  groups.flatMap((group) => group.tokens.map((token) => token.name));

/** What each token resolves to on an element */
export const readTokenValues = (element: Element, names: Array<string>): Record<string, string> => {
  const style = getComputedStyle(element);
  return Object.fromEntries(names.map((name) => [name, style.getPropertyValue(name).trim()]));
};

export const readRootFontSize = () => parseFloat(getComputedStyle(document.documentElement).fontSize);

/** The token values in the theme selected in the toolbar, read again when it changes */
const useTokenValues = (groups: Array<DesignTokenGroup>, theme: string) => {
  const rootRef = useRef<HTMLDivElement>(null);
  const [values, setValues] = useState<Record<string, string>>({});
  const [rootFontSize, setRootFontSize] = useState(16);

  useLayoutEffect(() => {
    if (!rootRef.current) return;

    setValues(readTokenValues(rootRef.current, getTokenNames(groups)));
    setRootFontSize(readRootFontSize());
  }, [groups, theme]);

  return { rootRef, values, rootFontSize };
};

type ColorScale = {
  /** What tells the scale apart from the others in the group, e.g. `primary` */
  label: string;
  /** The shared start of the token names, e.g. `--foundation-color-primary` */
  prefix: string;
  steps: Array<{ step: number; token: DesignToken }>;
};

const SCALE_STEP_PATTERN = /^(.+)-(\d+)$/;

/**
 * Splits a group of numbered colors into scales such as `primary-100` to `primary-900`. Undefined for any other
 * group. A color that is not set in the theme still belongs to its scale.
 */
const getColorScales = (tokens: Array<DesignToken>, values: Record<string, string>) => {
  const allSteps: Array<{ prefix: string; step: number; token: DesignToken }> = [];

  for (const token of tokens) {
    const match = token.name.match(SCALE_STEP_PATTERN);
    const value = values[token.name];
    const isColor = value ? getPreviewType(token.name, value) === "fill" : token.name.includes("color");
    if (!match || !isColor) return undefined;

    const [, prefix, step] = match;
    allSteps.push({ prefix, step: Number(step), token });
  }
  const scales = groupBy(allSteps, ({ prefix }) => prefix);
  if (scales.length === 0) return undefined;

  const prefixes = scales.map(({ key }) => key);
  // The label is what is left after the part all scales share, e.g. `--foundation-color-` for the park colors
  let sharedStart = prefixes.length > 1 ? prefixes[0] : "";
  prefixes.forEach((prefix) => {
    while (!prefix.startsWith(sharedStart)) sharedStart = sharedStart.slice(0, -1);
  });
  sharedStart = sharedStart.slice(0, sharedStart.lastIndexOf("-") + 1);
  // e.g. `text-color` becomes `Text color`
  const formatLabel = (label: string) => capitalizeFirstLetter(label.replace(/-/g, " "));

  return scales.map(
    ({ key: prefix, items }): ColorScale => ({
      label: formatLabel(prefixes.length > 1 ? prefix.slice(sharedStart.length) : prefix.split("-").pop() ?? prefix),
      prefix,
      steps: items.map(({ step, token }) => ({ step, token })).sort((a, b) => a.step - b.step),
    }),
  );
};

/** Each scale is a row and each step a column, so the same step lines up between scales, e.g. all 500s */
const ColorScales = ({ scales, values }: { scales: Array<ColorScale>; values: Record<string, string> }) => {
  const columns = [...new Set(scales.flatMap((scale) => scale.steps.map(({ step }) => step)))].sort((a, b) => a - b);

  return (
    <div className={styles.palette} style={{ "--palette-columns": columns.length } as CSSProperties}>
      {scales.map((scale) => {
        const isSet = scale.steps.some(({ token }) => values[token.name]);
        return (
          <div key={scale.prefix} className={styles.scale}>
            <div className={styles.scaleLabel}>
              <strong>{scale.label}</strong>
              <code>{scale.prefix}-*</code>
            </div>
            {!isSet && <em className={styles.scaleNotSet}>Not set in this theme</em>}
            {isSet &&
              scale.steps.map(({ step, token }) => {
                const value = values[token.name];
                return (
                  <CopyTokenButton
                    key={token.name}
                    name={token.name}
                    className={styles.paletteStep}
                    // The step's own column (after the label), so a gap is left where a scale skips a step
                    style={{ gridColumnStart: columns.indexOf(step) + 2 }}
                  >
                    {(copied) => (
                      <>
                        {value ? (
                          <Swatch name={token.name} className={styles.paletteColor} />
                        ) : (
                          <span className={styles.paletteColorNotSet} />
                        )}
                        <strong>{step}</strong>
                        <code>{copied ? "Copied" : value || "Not set"}</code>
                      </>
                    )}
                  </CopyTokenButton>
                );
              })}
          </div>
        );
      })}
    </div>
  );
};

export type TokenDefaultProps = { token: DesignToken; value: string };

/** The default in the less file, when it differs from the value it resolves to */
export const TokenDefault = ({ token, value }: TokenDefaultProps) =>
  token.definition && token.definition !== value ? (
    <span className={styles.definition}>
      default <code>{token.definition}</code>
    </span>
  ) : null;

const TokenTable = ({
  tokens,
  values,
  rootFontSize,
}: {
  tokens: Array<DesignToken>;
  values: Record<string, string>;
  rootFontSize: number;
}) => (
  <div className={styles.tableWrapper}>
    <table className={styles.table}>
      <thead>
        <tr>
          <th>Preview</th>
          <th>Token</th>
          <th>Value in selected theme</th>
        </tr>
      </thead>
      <tbody>
        {tokens.map((token) => {
          const value = values[token.name] ?? "";
          return (
            <tr key={token.name}>
              <td className={styles.preview}>
                <TokenPreview name={token.name} value={value} />
              </td>
              <td>
                <TokenNameButton name={token.name} />
                {token.comment && <p className={styles.comment}>{token.comment}</p>}
              </td>
              <td>
                {value ? formatValue(value, rootFontSize) : <em>Not set in this theme</em>}
                <TokenDefault token={token} value={value} />
              </td>
            </tr>
          );
        })}
      </tbody>
    </table>
  </div>
);

const TokenGroupContent = ({
  tokens,
  values,
  rootFontSize,
}: {
  tokens: Array<DesignToken>;
  values: Record<string, string>;
  rootFontSize: number;
}) => {
  const scales = getColorScales(tokens, values);
  return scales ? (
    <ColorScales scales={scales} values={values} />
  ) : (
    <TokenTable tokens={tokens} values={values} rootFontSize={rootFontSize} />
  );
};

/** A group in the URL, e.g. `segmented-controls` */
const getGroupSlug = (title: string) =>
  title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");

/** Shows one group at a time, picked in a select */
export type GroupPicker = {
  /** What a group is called on the page, e.g. `Component` */
  label: string;
  /** The first option, e.g. `All components` */
  allLabel: string;
  /** The slug of the picked group. Undefined, or a slug that matches no group, shows all groups. */
  selected?: string;
  /** Picks a group by its slug, or all groups with undefined */
  onSelect: (group?: string) => void;
};

/** How many name parts two tokens share after their level, e.g. 3 for `--component-media-gallery-block-a` and `-b` */
const countSharedNameParts = (first: string, second: string) => {
  const [a, b] = [first, second].map((name) => name.replace(/^--/, "").split("-").slice(1));
  let count = 0;
  while (count < a.length && a[count] === b[count]) count += 1;
  return count;
};

// Worked out once per page, the groups never change
const parkOnlyTokensCache = new WeakMap<Array<DesignTokenGroup>, Map<DesignTokenGroup, Array<DesignToken>>>();

/**
 * The park-only tokens that belong to each group, by the longest name start they share with the group's tokens, e.g.
 * `--component-media-gallery-block-padding` with Media Gallery Block. A tie goes to the group with more such tokens,
 * and a token without a clear group stays only in the park-only group.
 */
const getParkOnlyTokensByGroup = (groups: Array<DesignTokenGroup>) => {
  const cached = parkOnlyTokensCache.get(groups);
  if (cached) return cached;

  const byGroup = new Map<DesignTokenGroup, Array<DesignToken>>();
  groups
    .filter((group) => group.isParkOnly)
    .flatMap((group) => group.tokens)
    .forEach((token) => {
      const candidates = groups
        .filter((group) => !group.isParkOnly)
        .map((group) => {
          const shared = group.tokens.map((groupToken) => countSharedNameParts(token.name, groupToken.name));
          const score = Math.max(0, ...shared);
          return { group, score, count: shared.filter((parts) => parts === score).length };
        })
        .filter(({ score }) => score > 0)
        .sort((a, b) => b.score - a.score || b.count - a.count);
      const [best, next] = candidates;
      if (best && !(next && next.score === best.score && next.count === best.count)) {
        byGroup.set(best.group, [...(byGroup.get(best.group) ?? []), token]);
      }
    });

  parkOnlyTokensCache.set(groups, byGroup);
  return byGroup;
};

/** All groups, or the picked one followed by the park-only tokens that belong to it */
export const getPickedGroups = (groups: Array<DesignTokenGroup>, picker?: GroupPicker) => {
  const picked = groups.find((group) => picker?.selected && getGroupSlug(group.title) === picker.selected);
  if (!picked) return groups;

  const parkOnlyGroup = groups.find((group) => group.isParkOnly);
  const parkOnlyTokens = getParkOnlyTokensByGroup(groups).get(picked);
  return parkOnlyGroup && parkOnlyTokens ? [picked, { ...parkOnlyGroup, tokens: parkOnlyTokens }] : [picked];
};

export const countTokens = (groups: Array<DesignTokenGroup>) =>
  groups.reduce((count, group) => count + group.tokens.length, 0);

/** e.g. `1 token` or `12 tokens` */
export const formatTokenCount = (count: number) => `${count} ${count === 1 ? "token" : "tokens"}`;

/** The picked group in a message, e.g. ` in Buttons` in `No tokens in Buttons match`, or nothing for all groups */
export const getScope = (groups: Array<DesignTokenGroup>, pickedGroups: Array<DesignTokenGroup>) =>
  pickedGroups === groups ? "" : ` in ${pickedGroups[0].title}`;

export const getNoMatchMessage = (scope: string, search: string) => `No tokens${scope} match "${search}".`;

export type SearchFieldProps = { value: string; placeholder: string; onChange: (value: string) => void };

export const SearchField = ({ value, placeholder, onChange }: SearchFieldProps) => (
  <label className={styles.searchField}>
    Search
    <input type="search" value={value} placeholder={placeholder} onChange={(event) => onChange(event.target.value)} />
  </label>
);

export const GroupSelect = ({ groups, picker }: { groups: Array<DesignTokenGroup>; picker: GroupPicker }) => {
  const isPicked = getPickedGroups(groups, picker) !== groups;
  // A link to a group that no longer exists
  const isUnknown = !!picker.selected && !isPicked;
  const options = [
    ...groups.filter((group) => group.isParkOnly),
    ...groups.filter((group) => !group.isParkOnly).sort((a, b) => a.title.localeCompare(b.title, "en")),
  ];

  return (
    <label className={styles.searchField}>
      {picker.label}
      <select
        value={isPicked || isUnknown ? picker.selected : ""}
        onChange={(event) => picker.onSelect(event.target.value || undefined)}
      >
        <option value="">
          {picker.allLabel} ({countTokens(groups)})
        </option>
        {isUnknown && (
          <option value={picker.selected} disabled>
            No {picker.label.toLowerCase()} &quot;{picker.selected}&quot;, showing all
          </option>
        )}
        {options.map((group) => {
          const slug = getGroupSlug(group.title);
          return (
            <option key={group.title} value={slug}>
              {group.title} ({countTokens(getPickedGroups(groups, { ...picker, selected: slug }))})
            </option>
          );
        })}
      </select>
    </label>
  );
};

type DesignTokenPageProps = {
  /** Text shown above the tokens */
  intro: ReactNode;
  groups: Array<DesignTokenGroup>;
  /** Shown instead of the list when "Alla teman" is selected in the toolbar, e.g. `PaletteOverview` */
  allThemesView: ReactNode;
  /** The theme selected in the toolbar */
  theme: string;
  groupPicker?: GroupPicker;
};

/**
 * Lists design tokens with a preview and their value in the theme selected in the toolbar. Numbered color scales are
 * shown as palettes, everything else as a table.
 */
export const DesignTokenPage = ({ allThemesView, ...props }: DesignTokenPageProps) =>
  props.theme === ALL_THEMES ? <>{allThemesView}</> : <TokenList {...props} />;

/** Only the palette of a group, for "Alla teman", where the whole page in every theme would be thousands of rows */
export const PaletteOverview = ({ group }: { group: DesignTokenGroup }) => {
  const groups = useMemo(() => [group], [group]);
  const { rootRef, values, rootFontSize } = useTokenValues(groups, ALL_THEMES);

  return (
    <div ref={rootRef} className={styles.root}>
      <TokenGroupContent tokens={group.tokens} values={values} rootFontSize={rootFontSize} />
    </div>
  );
};

const TokenList = ({ intro, groups, theme, groupPicker }: Omit<DesignTokenPageProps, "allThemesView">) => {
  const { rootRef, values, rootFontSize } = useTokenValues(groups, theme);
  const [search, setSearch] = useState("");

  const pickedGroups = getPickedGroups(groups, groupPicker);
  const query = getSearchQuery(search);
  const matchesSearch = (group: DesignTokenGroup, token: DesignToken) =>
    getSearchText(group, token, [values[token.name]], rootFontSize).includes(query);
  const filteredGroups = pickedGroups
    .map((group) => ({ ...group, tokens: group.tokens.filter((token) => matchesSearch(group, token)) }))
    .filter((group) => group.tokens.length > 0);
  const tokenCount = countTokens(pickedGroups);
  const filteredTokenCount = countTokens(filteredGroups);
  const scope = getScope(groups, pickedGroups);

  return (
    <div ref={rootRef} className={multipleClassNames(styles.root, styles.page)}>
      <div className={styles.intro}>{intro}</div>

      <div className={styles.search}>
        {groupPicker && <GroupSelect groups={groups} picker={groupPicker} />}
        <SearchField
          value={search}
          placeholder="Name, value or group, e.g. primary-600, card or 16px"
          onChange={setSearch}
        />
        <p role="status">
          Showing {filteredTokenCount} of {formatTokenCount(tokenCount)}
        </p>
      </div>

      {filteredGroups.map((group) => (
        <section key={group.title} className={styles.group}>
          <h2 className="heading-s">{group.title}</h2>
          {group.notes.length > 0 && (
            <div className={styles.notes}>
              {group.notes.map((note) => (
                <p key={note}>{note}</p>
              ))}
            </div>
          )}
          <TokenGroupContent tokens={group.tokens} values={values} rootFontSize={rootFontSize} />
        </section>
      ))}

      {filteredGroups.length === 0 && <p>{getNoMatchMessage(scope, search)}</p>}
    </div>
  );
};
